"""Grouping helpers and department summaries."""

from __future__ import annotations

from .keys import order_records
from .records import normalize_records


def group_by_department(records):
    """Return a mapping from department to records in input order."""
    groups = {}
    for record in normalize_records(records):
        groups.setdefault(record["department"], []).append(record)
    return groups


def department_age_order(records):
    """Return department names ordered by descending age then name."""
    groups = group_by_department(records)
    return {
        department: [record["name"] for record in members]
        for department, members in groups.items()
    }


def department_summary(records):
    """Return one summary row per department."""
    groups = group_by_department(records)
    rows = []
    for department in sorted(groups):
        members = groups[department]
        total = sum(record["age"] for record in members)
        rows.append(
            {
                "department": department,
                "count": len(members),
                "average_age": round(total / len(members), 2),
                "names": [record["name"] for record in members],
            }
        )
    return rows

"""Validation and normalization for employee records."""

from __future__ import annotations

import re

REQUIRED_FIELDS = ("id", "name", "age", "department")
AGE_PATTERN = re.compile(r"^\d+$")
SPACE_PATTERN = re.compile(r"\s+")


def require_fields(record):
    """Check that a record is a mapping with every required field."""
    if not isinstance(record, dict):
        raise TypeError("record must be a dict")
    missing = [field for field in REQUIRED_FIELDS if field not in record]
    if missing:
        raise KeyError("missing fields: " + ", ".join(missing))


def parse_age(value):
    """Return an age as a non-negative integer."""
    if isinstance(value, bool):
        raise TypeError("age must not be boolean")
    if isinstance(value, int):
        age = value
    elif isinstance(value, str) and AGE_PATTERN.match(value.strip()):
        age = int(value.strip())
    else:
        raise ValueError("age must be a non-negative integer")
    if age < 0:
        raise ValueError("age must be non-negative")
    return age


def normalize_name(value):
    """Return a name with normalized internal spacing."""
    if not isinstance(value, str):
        raise TypeError("name must be a string")
    normalized = SPACE_PATTERN.sub(" ", value.strip())
    if not normalized:
        raise ValueError("name must not be empty")
    return normalized


def normalize_text(value, field):
    """Return trimmed text for a named field."""
    if not isinstance(value, str):
        raise TypeError(f"{field} must be a string")
    normalized = value.strip()
    if not normalized:
        raise ValueError(f"{field} must not be empty")
    return normalized


def normalize_record(record):
    """Return a validated copy of one record."""
    require_fields(record)
    return {
        "id": normalize_text(record["id"], "id"),
        "name": normalize_name(record["name"]),
        "age": parse_age(record["age"]),
        "department": normalize_text(record["department"], "department"),
    }


def normalize_records(records):
    """Return a list of validated record copies."""
    if isinstance(records, dict) or not isinstance(records, (list, tuple)):
        raise TypeError("records must be a list or tuple")
    return [normalize_record(record) for record in records]

"""Dictionary and text reports for employee records."""

from __future__ import annotations

from .grouping import department_summary
from .records import normalize_records
from .sorting import sort_records


def summary(records):
    """Return count, oldest, youngest and average age."""
    normalized = normalize_records(records)
    if not normalized:
        return {
            "count": 0,
            "oldest": None,
            "youngest": None,
            "average_age": 0,
        }
    ages = [record["age"] for record in normalized]
    oldest = max(normalized, key=lambda record: record["age"])
    youngest = min(normalized, key=lambda record: record["age"])
    return {
        "count": len(normalized),
        "oldest": oldest["name"],
        "youngest": youngest["name"],
        "average_age": round(sum(ages) / len(ages), 2),
    }


def name_list(records):
    """Return names in display order."""
    return [record["name"] for record in sort_records(records)]


def format_names(records, separator=", "):
    """Return names in display order joined by a separator."""
    return separator.join(name_list(records))


def department_lines(records):
    """Return one text line per department summary row."""
    return [
        f'{row["department"]}: {row["count"]} people, average {row["average_age"]}'
        for row in department_summary(records)
    ]


def format_table(records):
    """Return a tab separated table in display order."""
    rows = ["name\tage\tdepartment"]
    for record in sort_records(records):
        rows.append(
            f'{record["name"]}\t{record["age"]}\t{record["department"]}'
        )
    return "\n".join(rows)

